import 'dart:math' as math;
import 'dart:typed_data';
import 'dart:ui';

/// Point prompt guiding SAM 2.1 zero-shot mask decoder.
class Sam2PointPrompt {
  final double x;
  final double y;
  final bool isPositive;

  const Sam2PointPrompt({
    required this.x,
    required this.y,
    this.isPositive = true,
  });
}

/// Vision Transformer embedding generated by SAM 2.1 Hiera-Small encoder.
/// Grid dimensions: 64x64 spatial cells with 64 hierarchical feature channels.
class Sam2Embedding {
  static const int gridSize = 64;
  static const int channels = 64;
  static const int totalElements = gridSize * gridSize * channels;

  final Float32List data;
  final int sourceWidth;
  final int sourceHeight;

  Sam2Embedding({
    required this.data,
    required this.sourceWidth,
    required this.sourceHeight,
  }) : assert(
         data.length == totalElements,
         'SAM 2.1 embedding must have exactly $totalElements floats',
       );
}

/// Coordinate mapper translating Viewport tap positions to Source image space
/// with exact aspect-ratio letterbox/pillarbox compensation.
class Sam2CoordinateMapper {
  Sam2CoordinateMapper._();

  static Offset mapViewToSource({
    required Offset viewPosition,
    required Size viewSize,
    required int sourceWidth,
    required int sourceHeight,
  }) {
    if (sourceWidth <= 0 ||
        sourceHeight <= 0 ||
        viewSize.width <= 0 ||
        viewSize.height <= 0) {
      return Offset.zero;
    }

    final scale = math.min(
      viewSize.width / sourceWidth,
      viewSize.height / sourceHeight,
    );
    final renderedW = sourceWidth * scale;
    final renderedH = sourceHeight * scale;

    final offsetX = (viewSize.width - renderedW) * 0.5;
    final offsetY = (viewSize.height - renderedH) * 0.5;

    final srcX = ((viewPosition.dx - offsetX) / scale).clamp(
      0.0,
      sourceWidth - 1.0,
    );
    final srcY = ((viewPosition.dy - offsetY) / scale).clamp(
      0.0,
      sourceHeight - 1.0,
    );

    return Offset(srcX, srcY);
  }
}
